#!/usr/bin/env python3
"""The FL own-ship walk's two offsets not already generated by an FL provider, decoded from X3FL.exe (Capstone over
tools/analysis/inspect_x3.py's PE reader would do; this reads the PE directly): cockpit +0xc (the reference object)
and reference object +0x70 (its render root), at the anchors docs/reverse-engineering/fl/own-ship.md section 1 names.
The registry slot/layout (sector_background_fl_inc.h) and node +0x18 / +0x28 (object_trace_fl_inc.h) are generated
elsewhere. Prints the decoded instructions as one JSON line and exits 1 when an anchor does not decode as expected.

usage: python3 -I verification/results/fl-engine-effects/own_ship_offsets.py [X3FL.exe]
"""
import json
import struct
import sys

import capstone

EXE = sys.argv[1] if len(sys.argv) > 1 else '/mnt/c/X3FL/X3FL.exe'
# (VA at the preferred base, expected mnemonic, the memory operand's displacement, role)
ANCHORS = [
    (0x42241c, 'mov', 0xc, 'camera update reads the reference object from cockpit+0xc'),
    (0x422441, 'mov', 0x70, 'camera update reads the render root from ref+0x70'),
    (0x42246f, 'mov', 0x70, 'camera update reads the render root from ref+0x70 (second path)'),
    (0x430911, 'mov', 0xc, 'reference command stores the resolved object to cockpit+0xc'),
    (0x41a727, 'mov', 0xc, 'restore publishes the reference object to cockpit+0xc'),
    (0x449bdf, 'mov', 0x70, 'object initializer publishes the allocated render node to object+0x70'),
]


def main():
    data = open(EXE, 'rb').read()
    pe = struct.unpack_from('<I', data, 0x3c)[0]
    count = struct.unpack_from('<H', data, pe + 6)[0]
    optional = struct.unpack_from('<H', data, pe + 20)[0]
    sections = [struct.unpack_from('<8sIIII', data, pe + 24 + optional + 40 * i) for i in range(count)]

    def at(rva, n):
        for _, vsize, va, rsize, raw in sections:
            if va <= rva < va + vsize:
                return data[raw + rva - va:raw + rva - va + n]
        raise ValueError(hex(rva))

    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_32)
    md.detail = True
    rows, ok = [], True
    for va, mnemonic, disp, role in ANCHORS:
        insn = next(md.disasm(at(va - 0x400000, 16), va))
        mems = [op.mem.disp for op in insn.operands if op.type == capstone.x86.X86_OP_MEM]
        good = insn.mnemonic == mnemonic and disp in mems
        ok &= good
        rows.append(dict(va=hex(va), text=f'{insn.mnemonic} {insn.op_str}', expected_disp=hex(disp), ok=good, role=role))
    print(json.dumps(dict(exe=EXE, anchors=rows, passed=ok)))
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())
